import json, numpy as np
from scipy.spatial.transform import Rotation
s=json.load(open('/app/output/spec.json'))
p=np.array(json.load(open('/app/output/initial/meta.json'))['proprio']['now'])

def tf(p=(0,0,0),r=(0,0,0)):
 T=np.eye(4);T[:3,:3]=Rotation.from_euler('xyz',r).as_matrix();T[:3,3]=p;return T

def fk(q,tip=.1034):
 T=tf((0,-.4,.6),(0,0,np.pi/2))
 for qi,di,ai,al in zip(q,[.333,0,.316,0,.384,0,0],[0,0,0,.0825,-.0825,0,.088],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]):
  T=T@tf((ai,0,0),(al,0,0))@tf((0,0,di),(0,0,qi))
 return T@tf((0,0,.107+tip),(0,0,-np.pi/4))

if __name__=='__main__':
 for tip in [0,.1034]:
  T=fk(p[:7],tip);print('tip',tip, 'pos',T[:3,3],'quat',Rotation.from_matrix(T[:3,:3]).as_quat()[[3,0,1,2]])
 print('observed',p[16:23])
 for cam,coords in {'forward':[(81,247),(110,246),(130,247),(159,249),(188,249)],'right':[(182,247),(205,256),(230,266),(248,274),(278,284)],'left':[(91,265),(115,256),(139,247),(155,242),(173,235)]}.items():
  D=np.load('/app/output/initial/depth_'+cam+'.npy')[-1].astype(float);K=np.array(s['cameras'][cam]['intrinsic_cv']);C=np.array(s['cameras'][cam]['cam2world_gl'])
  print(cam,D.shape)
  for u,v in coords:
   z=D[v,u];pt=C@np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);print((u,v),z,pt[:3])
